.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 100;
  padding: 0.5rem 1rem;
  background: var(--color-btn-bg);
  color: var(--color-btn-text);
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; }

/* ── Base ────────────────────────────────────────────────────────────── */
html { font-size: 16px; }
body {
  font-family: var(--font);
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 2.5rem 1rem 4rem;
  line-height: 1.5;
}

/* ── Page header ─────────────────────────────────────────────────────── */
header {
  width: 100%;
  max-width: 520px;
  margin-bottom: 2rem;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--color-btn-bg);
  text-decoration: none;
  letter-spacing: -0.02em;
}
.brand-icon {
  width: 32px; height: 32px;
  background: var(--color-btn-bg);
  border-radius: var(--radius-sm);
  display: grid;
  place-items: center;
}
.brand-icon svg { color: #fff; }

/* ── Card ────────────────────────────────────────────────────────────── */
main { width: 100%; max-width: 520px; }

.card {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: 2.5rem 2.5rem 2rem;
}

.card-header { margin-bottom: 2rem; }
.card-header h1 {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.03em;
  color: var(--color-text);
  line-height: 1.25;
}
.card-header p {
  margin-top: 0.375rem;
  font-size: 0.9375rem;
  color: var(--color-text-muted);
}

/* ── Required legend ─────────────────────────────────────────────────── */
.required-note {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
  margin-bottom: 1.5rem;
}
.required-note span[aria-hidden="true"] {
  color: var(--color-required);
  font-weight: 700;
}

/* ── Form fields ─────────────────────────────────────────────────────── */
.form-field { display: flex; flex-direction: column; gap: 0.375rem; margin-bottom: 1.25rem; }
.form-field:last-of-type { margin-bottom: 0; }

label {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--color-text);
}
label .required-star {
  color: var(--color-required);
  margin-left: 0.2em;
  font-weight: 700;
}
label .optional-badge {
  font-weight: 400;
  color: var(--color-text-muted);
  font-size: 0.8125rem;
  margin-left: 0.35em;
}

input {
  width: 100%;
  padding: 0.625rem 0.875rem;
  font-size: 1rem;
  font-family: inherit;
  color: var(--color-text);
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-sm);
  transition: border-color var(--transition), box-shadow var(--transition);
  outline: none;
  appearance: none;
}
input::placeholder { color: var(--color-text-muted); opacity: 0.7; }
input:focus {
  border-color: var(--color-border-focus);
  box-shadow: 0 0 0 3px rgba(79,70,229,0.15);
}
input[aria-invalid="true"] {
  border-color: var(--color-border-error);
  background: var(--color-error-bg);
}
input[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgba(220,38,38,0.15);
}

/* ── Help / error text ───────────────────────────────────────────────── */
.help-text {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
  line-height: 1.4;
}

.error-text {
  font-size: 0.8125rem;
  color: var(--color-error-text);
  font-weight: 500;
  line-height: 1.4;
  display: none; /* hidden until triggered */
}
.error-text.visible { display: block; }

/* ── Submit button ───────────────────────────────────────────────────── */
.form-actions { margin-top: 1.75rem; }
.btn-submit {
  width: 100%;
  padding: 0.75rem 1.25rem;
  font-size: 1rem;
  font-family: inherit;
  font-weight: 600;
  color: var(--color-btn-text);
  background: var(--color-btn-bg);
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background var(--transition), transform 0.1s ease, box-shadow var(--transition);
  outline: none;
  letter-spacing: 0.01em;
}
.btn-submit:hover { background: var(--color-btn-hover); }
.btn-submit:focus-visible {
  box-shadow: 0 0 0 3px rgba(79,70,229,0.4);
}
.btn-submit:active { transform: translateY(1px); }

/* ── Status region ───────────────────────────────────────────────────── */
.status-region {
  margin-top: 1.25rem;
  border-radius: var(--radius-sm);
  font-size: 0.9375rem;
  font-weight: 500;
}
.status-region:not(:empty) { padding: 0.75rem 1rem; }
.status-region.success {
  background: var(--color-success-bg);
  color: var(--color-success-text);
  border: 1.5px solid #bbf7d0;
}
.status-region.error-summary {
  background: var(--color-error-bg);
  color: var(--color-error-text);
  border: 1.5px solid #fecaca;
}

/* ── Forced colors ───────────────────────────────────────────────────── */
@media (forced-colors: active) {
  input { border: 2px solid ButtonText; }
  input:focus { outline: 3px solid Highlight; }
  input[aria-invalid="true"] { border-color: LinkText; }
  .btn-submit { forced-color-adjust: none; background: Highlight; color: HighlightText; }
}

/* ── Reduced motion ──────────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0.01ms !important; }
}

/* ── Narrow viewport (320px reflow) ─────────────────────────────────── */
@media (max-width: 540px) {
  .card { padding: 1.75rem 1.25rem 1.5rem; border-radius: var(--radius-md); }
}
