/**
 * Contact form — validation and submission behaviour.
 *
 * Accessibility contract:
 *  - Errors are never shown on initial render.
 *  - On submit, invalid fields get aria-invalid="true" and their error
 *    elements become visible; focus moves to the first invalid field.
 *  - A polite live region announces success; an assertive alert announces
 *    the error count when focus doesn't move there.
 *  - aria-invalid is cleared and error text hidden as soon as the field
 *    value becomes valid (on 'input' event after first submit attempt).
 */

(function () {
  const form    = document.getElementById('contact-form');
  const status  = document.getElementById('form-status');
  let submitted = false; // track whether user has attempted a submit

  // ── Field descriptors ────────────────────────────────────────────────
  const fields = [
    {
      input:   document.getElementById('full-name'),
      error:   document.getElementById('full-name-error'),
      validate(val) {
        if (!val.trim()) return 'Error: Full name is required.';
        return null;
      },
    },
    {
      input:   document.getElementById('email'),
      error:   document.getElementById('email-error'),
      validate(val) {
        if (!val.trim()) return 'Error: Email address is required.';
        // basic structure check — the browser type="email" catches most
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val.trim())) {
          return 'Error: Enter a valid email address, e.g. name@example.com.';
        }
        return null;
      },
    },
    {
      input:    document.getElementById('phone'),
      error:    document.getElementById('phone-error'),
      optional: true,
      validate(val) {
        if (!val.trim()) return null; // optional — blank is fine
        // Allow digits, spaces, +, -, (, ) — at least 7 digits total
        const digits = val.replace(/\D/g, '');
        if (digits.length < 7 || digits.length > 15) {
          return 'Error: Enter a phone number between 7 and 15 digits, e.g. +1 (555) 000-1234.';
        }
        return null;
      },
    },
  ];

  // ── Helpers ──────────────────────────────────────────────────────────
  function setFieldError(field, message) {
    field.input.setAttribute('aria-invalid', 'true');
    field.error.textContent = message;
    field.error.classList.add('visible');
  }

  function clearFieldError(field) {
    field.input.removeAttribute('aria-invalid');
    field.error.textContent = '';
    field.error.classList.remove('visible');
  }

  function validateField(field) {
    const msg = field.validate(field.input.value);
    if (msg) {
      setFieldError(field, msg);
      return false;
    }
    clearFieldError(field);
    return true;
  }

  // ── Live re-validation after first submit attempt ────────────────────
  fields.forEach(field => {
    field.input.addEventListener('input', () => {
      if (!submitted) return;
      validateField(field);
    });
  });

  // ── Submit handler ───────────────────────────────────────────────────
  form.addEventListener('submit', function (e) {
    e.preventDefault();
    submitted = true;

    // Clear previous status
    status.textContent = '';
    status.className = 'status-region';

    const invalid = fields.filter(f => !validateField(f));

    if (invalid.length > 0) {
      // Move focus to first invalid field (focus change = no extra alert needed)
      invalid[0].input.focus();
      return;
    }

    // ── Simulate async submission ─────────────────────────────────────
    const btn = form.querySelector('.btn-submit');
    btn.disabled = true;
    btn.textContent = 'Sending…';

    setTimeout(() => {
      btn.disabled = false;
      btn.textContent = 'Send message';

      // Reset form state
      form.reset();
      submitted = false;
      fields.forEach(f => clearFieldError(f));

      // Announce success via polite live region
      status.className = 'status-region success';
      status.textContent = 'Your message has been sent. We'll be in touch soon.';
    }, 1200);
  });
})();
